import{_ as r,C as d,o as l,c as n,a2 as a,j as i,a as o,E as s}from"./chunks/framework.Dx-TCpNt.js";const q=JSON.parse('{"title":"FAQ とトラブルシューティング","description":"ページ欠落、言語フォルダ未認識、コマ検出のずれ、画像が出ないエクスポート、元画像が見つからない場合、デスクトップ版のデータフォルダ問題の対処。","frontmatter":{"description":"ページ欠落、言語フォルダ未認識、コマ検出のずれ、画像が出ないエクスポート、元画像が見つからない場合、デスクトップ版のデータフォルダ問題の対処。"},"headers":[],"relativePath":"ja/faq.md","filePath":"ja/faq.md","lastUpdated":1794821397000}'),c={name:"ja/faq.md"};function h(p,e,g,u,m,b){const t=d("Badge");return l(),n("div",null,[e[2]||(e[2]=a('<h1 id="faq-とトラブルシューティング" tabindex="-1">FAQ とトラブルシューティング <a class="header-anchor" href="#faq-とトラブルシューティング" aria-label="Permalink to &quot;FAQ とトラブルシューティング&quot;">​</a></h1><p>何かが壊れました。このページは症状から原因へさかのぼります——勘に頼る必要はありません。</p><h2 id="ライブラリが空です" tabindex="-1">ライブラリが空です <a class="header-anchor" href="#ライブラリが空です" aria-label="Permalink to &quot;ライブラリが空です&quot;">​</a></h2><p><strong>症状:</strong> サイドバーに「巻が見つかりません」と表示されます。</p><p><code>raw/</code> 以下のフォルダ構成を確認してください:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>raw/&lt;volume&gt;/&lt;language-dir&gt;/&lt;chapter&gt;/001.jpg</span></span></code></pre></div><p>よくある原因:</p><ul><li>巻フォルダはありますが、言語フォルダが認識されていません。巻の設定で対応付けるか、<code>ja</code>、<code>zh</code>、<code>en</code> に名前を変更してください（別名は <a href="/KomaYomi-docs/ja/guide/gallery">ライブラリ</a> に一覧があります）。</li><li>話フォルダが巻の直下にあります（<code>raw/&lt;volume&gt;/001.jpg</code>）。言語ディレクトリが必要です。</li><li>デスクトップアプリのデータディレクトリが別の場所を指しています。<code>Ctrl+Shift+D</code> を押して正しいフォルダを選ぶか、<code>MANGA_DATA_DIR</code> を設定してください。</li></ul><h2 id="あるページで言語が欠けています" tabindex="-1">あるページで言語が欠けています <a class="header-anchor" href="#あるページで言語が欠けています" aria-label="Permalink to &quot;あるページで言語が欠けています&quot;">​</a></h2><p><strong>症状:</strong> ページに <code>JA</code> と <code>ZH</code> しか表示されず、<code>EN</code> が無効になっています。</p><p>ページは並べ替えたインデックスで対応付けられます。その話で英語のファイルが1つ少ない場合、最後のページには英語の画像がありません。ページの警告に、欠けている言語とページ番号が示されます。ファイルを追加するか、余分なページを削除してください。</p><p>件数は一致しているのに、対応付けが誤っている場合は、ファイル名を確認してください。先頭の番号が並べ替えた位置と一致しない場合に警告が出ます。自然順が意図した順序になるようにファイル名を変更してください。</p><h2 id="ファイル名は問題ないのにページの順序がおかしい" tabindex="-1">ファイル名は問題ないのにページの順序がおかしい <a class="header-anchor" href="#ファイル名は問題ないのにページの順序がおかしい" aria-label="Permalink to &quot;ファイル名は問題ないのにページの順序がおかしい&quot;">​</a></h2><p>並べ替えは<strong>自然順</strong>です。数字の連続は数値として比較されるため、<code>2.jpg</code> は <code>10.jpg</code> より前に来ます。バイト単位の辞書順ではありません。先頭に番号のないファイルは、番号付きのファイルより前に並ぶことがあります。ページには <code>001.jpg</code>、<code>002.jpg</code> のように一貫した接頭辞を付けてください。</p><h2 id="コマ検出が正確ではありません" tabindex="-1">コマ検出が正確ではありません <a class="header-anchor" href="#コマ検出が正確ではありません" aria-label="Permalink to &quot;コマ検出が正確ではありません&quot;">​</a></h2><ul><li><strong>左右の縦帯は無視されます。</strong> これは意図的です。端の細い帯（通常は <em>あらすじ</em> や作者コメント）は、誤ったコマにならないようフィルターされます。正規の端のコマは手動で描いてください。</li><li><strong>見開きページ</strong> はしばしば1つの大きなコマと断片を生成します。断片を選択して <strong>結合</strong> してください。</li><li><strong>非常に小さい、または非常に細い枠</strong> はノイズとしてフィルターされます。実際に存在する場合は手動で追加してください。</li><li><strong>WebP はデコードされます。AVIF/HEIC はされません。</strong> 検出とサムネイルは WebP に対応しています。自動検出が必要なら AVIF、HEIC、GIF、BMP を JPEG/PNG に変換してください。</li><li><strong>固定の雑誌レイアウト</strong> には、検出よりも<a href="/KomaYomi-docs/ja/extending">レイアウトテンプレート</a>の方が適しています。</li></ul><p>コマを修正した後は、手動で描いた枠を失ってもよい場合を除き、自動検出を再実行しないでください。</p><h2 id="エクスポートした-html-に画像が表示されません" tabindex="-1">エクスポートした HTML に画像が表示されません <a class="header-anchor" href="#エクスポートした-html-に画像が表示されません" aria-label="Permalink to &quot;エクスポートした HTML に画像が表示されません&quot;">​</a></h2><p><strong>フォルダモード（既定）:</strong> HTML は隣接する <code>&lt;name&gt;.files/</code> ディレクトリを参照します。<code>.html</code> ファイルと <code>.files</code> フォルダを<strong>両方</strong>、相対位置を保ったままコピーしてください。HTML だけを開いたり、フォルダから離れた場所に移動したりすると、画像が壊れます。</p><p><strong>単一ファイルモード:</strong> 画像は埋め込まれているため、HTML ファイルだけが必要です。代償はサイズで、話全体では数十メガバイトになることがあります。</p><h2 id="元の画像が見つかりません" tabindex="-1">元の画像が見つかりません <a class="header-anchor" href="#元の画像が見つかりません" aria-label="Permalink to &quot;元の画像が見つかりません&quot;">​</a></h2><p><strong>症状:</strong> <code>.mnproj</code> のインポートで画像が見つからないと報告される、またはページに 404 のプレースホルダーが表示されます。</p><ul><li><strong>参照モードのプロジェクト</strong> はパスを保存し、画像は保存しません。画像が移動した場合は、再度インポートして<strong>再リンクディレクトリ</strong>を設定してください。インポーターはまず SHA-1 で、次にファイル名で照合し、巻名と話名を含むフォルダを優先します。</li><li><strong>パッケージモードのプロジェクト</strong> は画像を <code>assets/</code> に含みます。アセットが見つからない場合はパッケージが不完全なので、再エクスポートしてください。</li><li>画像は存在するが名前が変わっている場合は、期待される構造のフォルダに置いて再リンクを使ってください。</li></ul><h2 id="編集内容が消えました" tabindex="-1">編集内容が消えました <a class="header-anchor" href="#編集内容が消えました" aria-label="Permalink to &quot;編集内容が消えました&quot;">​</a></h2><p>ツールバーの保存モードを確認してください:</p><ul><li><strong>自動</strong> はデバウンスして保存します。</li><li><strong>確認</strong> は保存チェックのクリックが必要です。未保存の変更を残して離れるとブラウザの警告が出ますが、クラッシュや強制終了では最後の編集が失われることがあります。</li></ul><p>また、同じページを見ているか確認してください。URL ハッシュには巻、話、ページ、ビューが含まれます。別のデータディレクトリでアプリを開くと、別のライブラリが表示されます。</p><h2 id="テンプレートを適用したらコマのノートが消えました" tabindex="-1">テンプレートを適用したらコマのノートが消えました <a class="header-anchor" href="#テンプレートを適用したらコマのノートが消えました" aria-label="Permalink to &quot;テンプレートを適用したらコマのノートが消えました&quot;">​</a></h2><p>コマテンプレート（または再検出）でコマ数が変わると、コマスコープのノートは確実にマッピングできないため破棄されます。ページスコープのノートは常に保持されます。コマ数が変わらなければ、ノートは読み順で再マッピングされます。</p><p>これを避けるには、話全体にテンプレートを適用する前にバックアップをエクスポートしてください。</p><h2 id="ポート-5173-が既に使用されています" tabindex="-1">ポート 5173 が既に使用されています <a class="header-anchor" href="#ポート-5173-が既に使用されています" aria-label="Permalink to &quot;ポート 5173 が既に使用されています&quot;">​</a></h2><p>Vite は <code>strictPort: false</code> で設定されているため、次の空きポートに移動します。実際の URL はターミナルの出力を読んでください。ドキュメントサイトは <code>5174</code> を使います。</p><h2 id="すべてをバックアップするには" tabindex="-1">すべてをバックアップするには <a class="header-anchor" href="#すべてをバックアップするには" aria-label="Permalink to &quot;すべてをバックアップするには&quot;">​</a></h2><ul><li><strong>バックアップ ZIP</strong> — <code>data/</code> のすべて（JSON、テンプレート、プリセット）。サムネイルキャッシュを除きます。</li><li><strong><code>.mnproj</code></strong> — プロジェクトパッケージ。画像あり／なし。</li><li><strong>フォルダのコピー</strong> — <code>raw/</code> は画像、<code>data/</code> は作業内容、<code>exports/</code> は再生成可能です。</li></ul><p><a href="/KomaYomi-docs/ja/remote-backup">リモート保存とバックアップ</a> を参照してください。</p><h2 id="エラーコードが出たときは" tabindex="-1">エラーコードが出たときは <a class="header-anchor" href="#エラーコードが出たときは" aria-label="Permalink to &quot;エラーコードが出たときは&quot;">​</a></h2><p>サーバーと CLI は <code>ERR_*</code> / <code>WARN_*</code> / <code>STATUS_*</code> の安定したコードを返し、<code>error</code> / <code>message</code> の文言はリクエストの言語にローカライズされます。完全な一覧と HTTP 契約は<a href="/KomaYomi-docs/ja/server/error-codes">サーバーと CLI のメッセージコード</a>を参照してください。</p><h2 id="サムネイルが古い、または壊れて見えます" tabindex="-1">サムネイルが古い、または壊れて見えます <a class="header-anchor" href="#サムネイルが古い、または壊れて見えます" aria-label="Permalink to &quot;サムネイルが古い、または壊れて見えます&quot;">​</a></h2><p><code>data/cache/thumbs/</code> を削除してください。キャッシュであり、オンデマンドで再構築されます。バックアップとプロジェクトパッケージは既にこれを除外しています。</p><h2 id="ノートを検索しても何も返りません" tabindex="-1">ノートを検索しても何も返りません <a class="header-anchor" href="#ノートを検索しても何も返りません" aria-label="Permalink to &quot;ノートを検索しても何も返りません&quot;">​</a></h2><ul><li>検索はノート本文、タグ、出典を対象とします。有効な巻／話／タグ／出典のフィルターを確認してください。</li><li>ノートはインデックスされるために<strong>保存</strong>されている必要があります。確認モードでは、未保存の編集はまだディスクにありません。</li><li>一覧 / 検索はページ JSON をインデックスします。保存に失敗したページには検索可能なノートがありません。</li></ul><h2 id="デスクトップアプリは起動するが古いページ群が表示されます" tabindex="-1">デスクトップアプリは起動するが古いページ群が表示されます <a class="header-anchor" href="#デスクトップアプリは起動するが古いページ群が表示されます" aria-label="Permalink to &quot;デスクトップアプリは起動するが古いページ群が表示されます&quot;">​</a></h2><p>デスクトップウィンドウがリポジトリとは別のデータディレクトリを使っている可能性があります。ウィンドウタイトル（データパスを含みます）を確認し、<code>Ctrl+Shift+D</code> を押して切り替えてください。<code>MANGA_DATA_DIR</code> は保存された設定を上書きします。</p><h2 id="pdf-や-word-はどう書き出しますか" tabindex="-1">PDF や Word はどう書き出しますか <a class="header-anchor" href="#pdf-や-word-はどう書き出しますか" aria-label="Permalink to &quot;PDF や Word はどう書き出しますか&quot;">​</a></h2><p><code>E</code> を押し、エクスポートダイアログで <strong>PDF（印刷）</strong> または <strong>Word 文書</strong> を選びます。</p><ul><li><strong>PDF（印刷）</strong> は印刷ページを開き、ブラウザの印刷ダイアログを呼び出します。そこで <strong>PDF に保存</strong> を選んでください。</li><li><strong>Word 文書</strong> は、ページ画像と、編集可能なテキストに変換されたページ／コマノートを含む <code>.docx</code> をダウンロードします。注釈は既定でページ画像に焼き込まれ、合成できなかったページは元の画像に戻って <code>WARN_EXPORT_ANNOTATIONS_UNBAKED</code> の警告が付きます。</li></ul>',46)),i("p",null,[e[0]||(e[0]=o("語彙リストのエクスポートは引き続き ",-1)),s(t,{type:"warning",text:"予定"}),e[1]||(e[1]=o(" です。",-1))]),e[3]||(e[3]=a('<h2 id="コマのグループはどう作りますか" tabindex="-1">コマのグループはどう作りますか <a class="header-anchor" href="#コマのグループはどう作りますか" aria-label="Permalink to &quot;コマのグループはどう作りますか&quot;">​</a></h2><p>コマ分割ワークベンチでコマを 1 つ以上選び、<strong>グループ化</strong>を押します。新しいグループは<strong>グループ</strong>パネルに表示され、名前、色、チップの順序、前のグループへの統合、分割、削除を編集できます。グループを削除してもコマは残ります。<strong>グループ順に整列</strong>はグループ順にページを振り直します。グループはページ交換ファイル、プロジェクトパッケージ、エクスポートで保持されます。<a href="/KomaYomi-docs/ja/guide/panels#グループ">コマ分割ワークベンチ</a>を参照してください。ベクター<strong>注釈</strong>も実装済みで、矢印、矩形、楕円、ハイライト、フリーハンド、テキスト、バッジ、モザイクが使えます。</p><h2 id="データはどこかに送信されますか" tabindex="-1">データはどこかに送信されますか <a class="header-anchor" href="#データはどこかに送信されますか" aria-label="Permalink to &quot;データはどこかに送信されますか&quot;">​</a></h2><p>既定ではいいえ。サーバーは <code>127.0.0.1</code> で待ち受け、リモート先を設定しない限り何もアップロードされません。外向きリクエストは 2 種類あります。ノートの出典のための任意の「ページタイトルを取得」（入力した URL を5秒のタイムアウトで要求）と、自分で追加した WebDAV／ネットワークストレージ先（画像のオンデマンド取得とバックアップのアップロード）です。ストレージ先を設定しなければ、すべてのデータはローカルに留まります。</p><h2 id="古いページ-json-が開きません" tabindex="-1">古いページ JSON が開きません <a class="header-anchor" href="#古いページ-json-が開きません" aria-label="Permalink to &quot;古いページ JSON が開きません&quot;">​</a></h2><p>手で編集した、または古い JSON は読み込み時に正規化されます。欠けた id は生成され、矩形はクランプされ、無効な enum 値は既定値にフォールバックし、ぶら下がったグループ参照は削除されます。ファイルがまったく有効な JSON でない場合、アプリはそのページにデータがないものとして扱い、再検出します。その結果、保存時にファイルが上書きされます。その場合はバックアップから復元してください。</p><h2 id="それ以外の問題があります" tabindex="-1">それ以外の問題があります <a class="header-anchor" href="#それ以外の問題があります" aria-label="Permalink to &quot;それ以外の問題があります&quot;">​</a></h2><p>助けを求める前に、次を集めてください。未来のあなたが助かります:</p><ol><li><code>npm run dev</code> または <code>npm run desktop</code> を起動したターミナルの出力。</li><li>正確なページのパス（<code>data/pages/&lt;volume&gt;/&lt;chapter&gt;/&lt;index&gt;.json</code>）。</li><li><code>data/cache/thumbs/</code> を削除した後に問題が再現するかどうか。</li><li>検出に関する問題なら <code>node scripts/manga-cli.ts report</code> の出力。</li></ol>',9))])}const P=r(c,[["render",h]]);export{q as __pageData,P as default};
